<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_login();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$medium=(string)(user()['medium']??'English');
$l=$id?query_one("SELECT l.*,s.name_en,s.name_si,s.name_ta,s.icon,u.name_en unit_name_en,u.name_si unit_name_si,u.name_ta unit_name_ta FROM lessons l JOIN subjects s ON s.id=l.subject_id JOIN units u ON u.id=l.unit_id WHERE l.id=? AND l.grade_id=? AND l.status='active' AND l.content_source='textbook' AND (l.medium='All' OR l.medium=?)",'iis',[$id,user()['grade_id'],$medium]):null;
if(!$l){flash('error','Invalid lesson.');redirect('student/lessons.php');}$uid=(int)user()['id'];
require_lesson_access((int)$id);
$mainQuizType=in_array(user_grade_number(),[6,7,8,9,10],true)?'challenge':'lesson_quiz';$mainQuizLabel=$mainQuizType==='challenge'?'Quick Challenge':'Lesson Quiz';$removeQuickChallenge=user_grade_number()===6&&$medium==='Sinhala'&&($l['name_en']??'')==='Buddhism'&&(int)$l['display_order']===1;
$quizInfo=query_one("SELECT q.id,(SELECT COUNT(*) FROM quiz_questions qq WHERE qq.quiz_id=q.id AND qq.activity_type=? AND qq.status='active') lesson_questions,(SELECT COUNT(DISTINCT qq.activity_type) FROM quiz_questions qq WHERE qq.quiz_id=q.id AND qq.activity_type IN ('challenge','missing','matching') AND qq.status='active') practice_types FROM quizzes q WHERE q.lesson_id=? AND q.status='active' ORDER BY q.id LIMIT 1",'si',[$mainQuizType,$id]);$quizAvailable=(int)($quizInfo['lesson_questions']??0)>0;$practiceRequired=(int)($quizInfo['practice_types']??0);
if(!$quizAvailable){$quizInfo=query_one("SELECT q.id,(SELECT COUNT(*) FROM quiz_questions qq WHERE qq.quiz_id=q.id AND qq.activity_type=? AND qq.status='active') lesson_questions,(SELECT COUNT(DISTINCT qq.activity_type) FROM quiz_questions qq WHERE qq.quiz_id=q.id AND qq.activity_type IN ('challenge','missing','matching') AND qq.status='active') practice_types FROM quizzes q JOIN lessons ql ON ql.id=q.lesson_id WHERE ql.grade_id=? AND ql.subject_id=? AND ql.display_order=? AND (ql.medium='All' OR ql.medium=?) AND q.status='active' ORDER BY lesson_questions DESC,q.id LIMIT 1",'siiis',[$mainQuizType,$l['grade_id'],$l['subject_id'],$l['display_order'],$l['medium']]);$quizAvailable=(int)($quizInfo['lesson_questions']??0)>0;}
$practiceRequired=(int)($quizInfo['practice_types']??0);
$practiceRow=query_one("SELECT COUNT(DISTINCT CASE WHEN detail LIKE 'Quick Challenge - %' THEN 'challenge' WHEN detail LIKE 'Fill the Missing Answer - %' THEN 'missing' WHEN detail LIKE 'Matching Mission - %' THEN 'matching' END) completed FROM student_activity_events WHERE user_id=? AND lesson_id=? AND event_type='quiz_completed'",'ii',[$uid,$id]);$practiceCompleted=(int)($practiceRow['completed']??0);if($removeQuickChallenge){$quizAvailable=false;$practiceRequired=max(0,$practiceRequired-1);}$practiceReady=$practiceCompleted>=$practiceRequired;$quizPerfect=$quizAvailable&&query_one('SELECT qa.id FROM quiz_attempts qa JOIN quizzes q ON q.id=qa.quiz_id WHERE qa.user_id=? AND q.lesson_id=? AND qa.total_questions>0 AND qa.score=qa.total_questions LIMIT 1','ii',[$uid,$id])!==null;$completionReady=$quizAvailable?$quizPerfect:$practiceReady;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();if(!$completionReady){flash('warning',$quizAvailable?'Reach 100% in the '.$mainQuizLabel.' to complete this lesson.':'Complete the available Practice Lab activities before finishing this lesson.');redirect($quizAvailable?'student/quiz.php?id='.(int)$quizInfo['id']:'student/activities.php?lesson_id='.$id);}
 // Complete the lesson with an atomic state transition. This makes repeated
 // clicks (including simultaneous requests) harmless and awards points once.
 $db=db();$db->begin_transaction();
 $s=$db->prepare('INSERT INTO lesson_progress(user_id,lesson_id,opened_at,last_opened_at,completed_at) VALUES(?,?,NOW(),NOW(),NULL) ON DUPLICATE KEY UPDATE last_opened_at=NOW()');$s->bind_param('ii',$uid,$id);$s->execute();$s->close();
 $s=$db->prepare('UPDATE lesson_progress SET completed_at=NOW(),last_opened_at=NOW() WHERE user_id=? AND lesson_id=? AND completed_at IS NULL');$s->bind_param('ii',$uid,$id);$s->execute();$newlyCompleted=$s->affected_rows===1;$s->close();$db->commit();
 if(!$newlyCompleted){flash('success','This lesson is already completed. No additional points were awarded.');redirect('student/lesson.php?id='.$id);}
 $points=reward_lesson_completion($uid,$l);record_student_activity($uid,'lesson_completed',(string)locale_value($l,'title'),(int)$l['subject_id'],$id);
 redirect('student/lesson.php?id='.$id.'&celebrate=1&points='.$points);
}
$s=db()->prepare('INSERT INTO lesson_progress(user_id,lesson_id,opened_at,last_opened_at) VALUES(?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE last_opened_at=NOW()');$s->bind_param('ii',$uid,$id);$s->execute();record_student_activity($uid,'lesson_opened',(string)locale_value($l,'title'),(int)$l['subject_id'],$id);
$progress=query_one('SELECT completed_at FROM lesson_progress WHERE user_id=? AND lesson_id=?','ii',[$uid,$id]);$completed=!empty($progress['completed_at']);
$prev=query_one("SELECT id FROM lessons WHERE subject_id=? AND status='active' AND content_source='textbook' AND (medium='All' OR medium=?) AND display_order<? ORDER BY display_order DESC LIMIT 1",'isi',[$l['subject_id'],$medium,$l['display_order']]);
$next=query_one("SELECT id FROM lessons WHERE subject_id=? AND status='active' AND content_source='textbook' AND (medium='All' OR medium=?) AND display_order>? ORDER BY display_order LIMIT 1",'isi',[$l['subject_id'],$medium,$l['display_order']]);
$earned=query_one("SELECT tier FROM student_emblems WHERE user_id=? AND lesson_id=? ORDER BY FIELD(tier,'master','gold','silver','bronze') LIMIT 1",'ii',[$uid,$id]);
$bookSource=query_one('SELECT local_file,start_page FROM lesson_source_pdfs WHERE lesson_id=?','i',[$id]);
$bookUrl='';
if($bookSource){
 $bookRelative=str_replace('\\','/',trim((string)$bookSource['local_file']));
 if(preg_match('#^uploads/syllabus/.+\.pdf$#i',$bookRelative)&&!preg_match('#(?:^|/)\.\.(?:/|$)#',$bookRelative)){
  $bookUrl=is_premium()?url('student/lesson_pdf.php?id='.(int)$id):url('subscription.php');
 }
}
function lesson_items(string $text,int $limit=6):array{$parts=preg_split('/(?:\r?\n)+|(?<=[.!?])\s+/u',trim($text))?:[];return array_slice(array_values(array_filter(array_map('trim',$parts),fn($x)=>mb_strlen($x)>2)),0,$limit);}
$previewNotice=!is_premium();
$objectives=lesson_items(markdown_plain_text((string)locale_value($l,'learning_objectives')),4);$summary=lesson_items(markdown_plain_text((string)locale_value($l,'summary')),6);$terms=lesson_items(markdown_plain_text((string)locale_value($l,'key_terms')),8);$shortNotes=(string)locale_value($l,'short_notes');if(trim($shortNotes)==='')$shortNotes=(string)locale_value($l,'summary');$pageTitle=locale_value($l,'title');include __DIR__.'/../includes/header.php';
?>
